// Permission-preset seeding (S1 step 3, docs/plans/arxa-isolation-levels.md).
//
// The live exposure — `permission.defaultPreset: danger-full-access` — is
// closed by seeding `workspace-write` into ~/.arxa/dsh/settings.yaml. The one
// rule that makes the flip safe for existing installs:
//
//   an existing profile migrates ONLY when a launcher-owned marker proves the
//   on-disk value was generated by this launcher; an indistinguishable
//   operator value stays untouched and gets a visible remediation notice.
//
// The marker is a YAML comment naming the seeded value, written beside it:
//
//   permission:
//     # arxa-studio-seeded: permission.defaultPreset=workspace-write v1
//     defaultPreset: workspace-write
//
// Marker value == current value  → arxa generated it; a later arxa default
// may rewrite it (and move the marker). Marker value != current value → the
// operator edited it since; the edit always wins. No marker at all → the
// value predates markers or was hand-set; indistinguishable, so kept.
//
// Line-based, like the agent-presets migration beside it in bin/arxa-studio.mjs:
// every other byte of an existing settings.yaml — comments included — survives.
// Pure: the caller owns the file and the printing.

/** The marker format version. Bump only when the marker semantics change. */
export const MARKER_VERSION = 1

/**
 * The marker line for a seeded value.
 * @param {string} preset - the preset value the marker proves.
 * @returns {string} the comment line (no trailing newline).
 */
export function markerFor (preset) {
  return `# arxa-studio-seeded: permission.defaultPreset=${preset} v${MARKER_VERSION}`
}

const MARKER_RE = /^[ \t]*# arxa-studio-seeded: permission\.defaultPreset=(\S+) v(\d+)$/m

/** @returns {string | undefined} the current defaultPreset, when the block exists. */
function currentValue (lines) {
  const idx = lines.findIndex((l) => l === 'permission:')
  if (idx === -1) return undefined
  for (let i = idx + 1; i < lines.length && (lines[i] === '' || /^[ \t]/.test(lines[i])); i++) {
    const m = lines[i].match(/^[ \t]*defaultPreset:[ \t]*(\S+)[ \t]*$/)
    if (m) return m[1]
  }
  return undefined
}

/**
 * Decide what happens to an existing settings.yaml's permission.defaultPreset.
 *
 * @param {string} raw - the file's current bytes.
 * @param {object} [opts]
 * @param {string} [opts.preset] - the preset arxa seeds ('workspace-write').
 * @returns {{ text: string, action: 'kept' | 'migrated', notice?: string }} the
 *   (possibly rewritten) text and the stdout notice to print, if any.
 */
export function seedPermissionPreset (raw, { preset = 'workspace-write' } = {}) {
  const marker = MARKER_RE.exec(raw)
  const current = currentValue(raw.split('\n'))

  const kept = (notice) => ({ text: raw, action: 'kept', notice })

  if (current === undefined) {
    return kept(`arxa: settings.yaml has no permission.defaultPreset — arxa recommends '${preset}' (per-worktree write confinement). Add:\n  permission:\n${markerFor(preset)}\n    defaultPreset: ${preset}`)
  }
  if (marker === null) {
    // No proof the value was generated here: an operator's deliberate choice
    // and a pre-marker arxa seed are indistinguishable, and the safe read is
    // the operator's. Visible remediation, never a silent overwrite.
    return kept(`arxa: settings.yaml permission.defaultPreset is '${current}' with no arxa marker — arxa recommends '${preset}' (per-worktree write confinement) but will not touch a value it cannot prove it generated. To adopt:\n  permission:\n${markerFor(preset)}\n    defaultPreset: ${preset}`)
  }
  if (marker[1] !== current) {
    return kept(`arxa: settings.yaml permission.defaultPreset was edited to '${current}' after arxa seeded '${marker[1]}' — keeping the operator's value.`)
  }
  if (current === preset) return kept(undefined)

  const lines = raw.split('\n')
  const idx = lines.findIndex((l) => l === 'permission:')
  for (let i = idx + 1; i < lines.length && (lines[i] === '' || /^[ \t]/.test(lines[i])); i++) {
    const m = lines[i].match(/^([ \t]*defaultPreset:[ \t]*)\S+[ \t]*$/)
    if (m) {
      lines[i] = m[1] + preset
      // Move the marker with the value it proves.
      const mIdx = lines.findIndex((l) => MARKER_RE.test(l))
      if (mIdx !== -1) lines[mIdx] = markerFor(preset)
      const text = lines.join('\n')
      return {
        text,
        action: 'migrated',
        notice: `arxa: settings.yaml permission.defaultPreset was '${current}' (seeded by an earlier arxa) — set to '${preset}'.`
      }
    }
  }
  // defaultPreset existed but no longer matches the line shape — treat as kept.
  return kept(undefined)
}

/**
 * The fresh-seed permission block (with its marker) for a new settings.yaml.
 * @param {string} [preset] - the preset arxa seeds.
 * @returns {string} YAML lines, indented to sit inside the seeded file.
 */
export function seededPermissionBlock (preset = 'workspace-write') {
  return `permission:\n  ${markerFor(preset)}\n  defaultPreset: ${preset}\n`
}
